  insert into public.brands (name, website, description, country, status) values ('Aliangé', 'https://aliange.com.au', 'Australian doctor-led clinical skincare brand (founded by Dr Alison Jamieson) running its affiliate program through Shopify Collabs on its own site: 20% commission on every order with no caps, a 90-day cookie, typical orders over $200 AUD, commission clearing 90 days after each sale, a $50 payout threshold and PayPal withdrawal; open to everyone with approval inside about 48 hours.', null, 'published') returning id into bid;
  insert into public.brand_categories (brand_id, category_id, is_primary) values (bid, (select id from public.categories where slug = 'skincare'), true);
  insert into public.brand_contacts (brand_id, contact_type, email, contact_url, source_url, verification_status, last_verified_at) values (bid, 'general', 'customerservice@aliange.com.au', null, null, 'needs_review', null);
  insert into public.affiliate_programs (brand_id, network, commission_rate, commission_notes, application_url, status, last_checked_at) values (bid, 'Shopify Collabs (brand portal)', 20, 'Commission cap: UNCAPPED — stated in the program terms (see evidence). Creator saturation: unknown (see evidence). Rate as reported by https://aliange.com.au/pages/affiliate.', 'https://aliange.com.au/pages/affiliate', 'needs_review', now());
  insert into public.opportunities (brand_id, title, application_url, source_url, status, opportunity_type) values (bid, 'Aliangé Affiliate Program (Shopify Collabs)', 'https://aliange.com.au/pages/affiliate', null, 'unverified', 'ugc');
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://aliange.com.au/pages/affiliate', 'brand_site', 'affiliate_program', 'Aliangé''s official affiliate page states affiliates earn 20% commission on every order, tracked through Shopify Collabs with a 90-day cookie; commission clears 90 days after the sale, payouts are via PayPal once earnings reach the $50 threshold, the program is open to everyone, applications are approved within about 48 hours, and typical orders exceed $200 AUD.', 'verified', now());
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://aliange.com.au/pages/affiliate', 'brand_site', 'commission_cap', 'The brand''s own affiliate page and its FAQ state the no-cap position explicitly and repeatedly, including the FAQ wording ''20% commission on every order, with no caps'' — an explicit earnings no-cap statement on the brand''s own page, so commission_cap is recorded as uncapped. No absolute creator counts are published, so creator_saturation stays unknown.', 'verified', now());
  insert into public.brand_scores (brand_id, niche_fit, ugc_evidence, compensation, contact_access, opportunity_availability, credibility, explanation) values (bid, 24, 15, 17, 9, 8, 3, '{"compensation": "20% on every order with an explicit no-cap statement on the brand''s own page; high typical order values (over $200 AUD) partly offset by commission clearing only 90 days after each sale.", "contact_access": "Full program page and FAQ on the brand''s own domain with a published contact email; self-serve application via Shopify Collabs.", "credibility": "Doctor-led Australian clinical skincare brand with complete published program terms; smaller and less widely distributed than the global names in this batch.", "niche_fit": "Clinical skincare with high order values \u2014 strong material for routine, results and before/after UGC.", "opportunity_availability": "Open to everyone with approval inside about 48 hours; no follower minimum published.", "ugc_evidence": "A dedicated affiliate page pitched at promoters with tracked links, a long 90-day cookie and PayPal cash-out \u2014 a genuine creator monetization route, though no separate UGC content program is published."}'::jsonb);
  insert into public.brands (name, website, description, country, status) values ('KISS USA', 'https://www.kissusa.com', 'US beauty giant behind KISS nails and lashes, imPRESS press-on nails, FALSCARA and KISS Colors & Care, running its own affiliate program from its own site: tiered commission structures across its brand lines, universal cart tracking across its four web stores, dedicated affiliate managers and creative assets; US and Canada only, with no published commission rate and no cap statement.', null, 'published') returning id into bid;
