  insert into public.opportunities (brand_id, title, application_url, source_url, status, opportunity_type) values (bid, 'KISS USA Affiliate Program', 'https://www.kissusa.com/pages/affiliate-program', null, 'unverified', 'ugc');
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://www.kissusa.com/pages/affiliate-program', 'brand_site', 'affiliate_program', 'KISS USA''s official Affiliate Program page describes tiered commission structures spanning its KISS, imPRESS, FALSCARA and KISS Colors & Care lines, universal cart tracking across its four sites, dedicated affiliate managers and creative assets, and eligibility limited to the US and Canada.', 'verified', now());
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://www.kissusa.com/pages/affiliate-program', 'brand_site', 'commission_cap', 'The brand''s program page publishes no commission percentage and no earnings-cap statement, so commission_rate is recorded as null and commission_cap as unknown (not uncapped). No absolute creator counts are published, so creator_saturation stays unknown.', 'verified', now());
  insert into public.brand_scores (brand_id, niche_fit, ugc_evidence, compensation, contact_access, opportunity_availability, credibility, explanation) values (bid, 25, 15, 8, 8, 8, 5, '{"compensation": "Tiered commission structures are confirmed on the brand''s own page, but no percentage is published anywhere, so the rate is null and compensation scores low.", "contact_access": "Full program page on the brand''s own domain with self-serve application and named program support (affiliate managers); no public email.", "credibility": "One of the largest US nail and lash brands, sold nationwide for decades, with a complete program page on its own domain.", "niche_fit": "Press-on nails, lashes and hair color are among the most UGC-friendly beauty categories \u2014 application and wear-test content is a proven format.", "opportunity_availability": "Open application on the brand''s own site; restricted to US and Canada affiliates.", "ugc_evidence": "A dedicated own-site affiliate program with creative assets and manager support aimed at content promoters across four consumer brand lines."}'::jsonb);
  insert into public.brands (name, website, description, country, status) values ('Medik8', 'https://www.medik8.com', 'UK science-led skincare brand founded in 2009 by scientists Elliot and Daniel Isaacs, known for results-focused, age-defying formulas. Its affiliate programme runs on Awin at up to 10% commission with a 30-day cookie and a £65 average order value, with manual approval; a US route via CJ Affiliate at 10% is also listed by LinkClicky.', null, 'published') returning id into bid;
