  insert into public.opportunities (brand_id, title, application_url, source_url, status, opportunity_type) values (bid, 'Medik8 Affiliate Programme (Awin)', 'https://ui.awin.com/merchant-profile/99011?setLocale=sv_SE', null, 'unverified', 'ugc');
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://ui.awin.com/merchant-profile/99011?setLocale=sv_SE', 'network_profile', 'affiliate_program', 'Medik8''s official Awin merchant profile (''Medik8 Limited Affiliate Programme'') states: commission up to 10%, 30-day cookie length, £65 average order value, manual affiliate approval, regularly updated creatives and datafeed, and the program contact email medik8@revwise.com. The recorded rate of 10 is that published ''up to 10%'' figure. LinkClicky separately lists a US Medik8 program on CJ Affiliate at 10% per sale.', 'verified', now());
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://ui.awin.com/merchant-profile/99011?setLocale=sv_SE', 'network_profile', 'commission_cap', 'The Awin profile contains no statement about an earnings cap or limit, so commission_cap is recorded as unknown (not uncapped). No absolute creator counts are published, so creator_saturation stays unknown.', 'verified', now());
  insert into public.brand_scores (brand_id, niche_fit, ugc_evidence, compensation, contact_access, opportunity_availability, credibility, explanation) values (bid, 24, 13, 12, 12, 7, 5, '{"compensation": "Up to 10% on Awin with a healthy \u00a365 average order value and a 30-day cookie; the 10% is a published ceiling, not a flat rate.", "contact_access": "A named program contact email is published on the official Awin profile, on top of standard network application.", "credibility": "Established UK skincare brand founded in 2009, widely retailed, with a complete official network profile and terms.", "niche_fit": "Premium results-driven skincare (retinal, vitamin C, SPF) is core skincare-creator material with strong review and routine demand.", "opportunity_availability": "Open application on Awin but with manual approval; a second US route exists via CJ Affiliate.", "ugc_evidence": "A staffed network programme with creatives and a datafeed; pitched at publishers generally rather than a dedicated creator program, so UGC evidence is moderate."}'::jsonb);
  insert into public.brands (name, website, description, country, status) values ('Celladix', 'https://celladix.us', 'K-beauty skincare brand selling in the US through 2359 US Inc., with a published Affiliate Program Agreement on its own site: the program runs on BixGrow, commission is set per Offer rather than published in the terms, and the agreement explicitly permits affiliates to promote on Facebook, Instagram, TikTok and YouTube.', null, 'published') returning id into bid;
