  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://celladix.us/pages/affiliate-terms', 'brand_site', 'affiliate_program', 'Celladix''s official Affiliate Program Agreement (operated by 2359 US Inc., program run via BixGrow) sets commission per individual Offer rather than publishing a rate in the terms, and expressly permits affiliate promotion across Facebook, Instagram, TikTok and YouTube. The agreement also publishes the brand''s PR contact, pr@Celladix.com.', 'verified', now());
