  insert into public.brand_scores (brand_id, niche_fit, ugc_evidence, compensation, contact_access, opportunity_availability, credibility, explanation) values (bid, 21, 12, 7, 11, 7, 3, '{"compensation": "A real commission program exists in the brand''s own terms, but the rate is set per Offer and never published, so the rate is null and compensation scores low.", "contact_access": "A published PR email inside the brand''s own program agreement, plus the full terms on the brand''s own domain.", "credibility": "Smaller K-beauty entrant in the US market; the published legal agreement is a positive sign, but the brand''s track record is short.", "niche_fit": "K-beauty skincare is a proven UGC category; a smaller brand means less existing content demand than the big K-beauty names.", "opportunity_availability": "Program terms are public and social promotion is explicitly permitted; the actual Offer rates are only visible after joining.", "ugc_evidence": "The agreement is written for social promoters \u2014 it names Instagram, TikTok, YouTube and Facebook as permitted channels \u2014 but there is no separate creator program page."}'::jsonb);
  insert into public.brands (name, website, description, country, status) values ('UpCircle Beauty', 'https://us.upcirclebeauty.com', 'UK-born sustainable skincare brand (a certified B Corp) that formulates face, body and hair products from upcycled ingredients such as coffee grounds and fruit stones, stocked in over 55 countries. Its affiliate program runs on CJ Affiliate at 5% per sale with a 14-day cookie.', null, 'published') returning id into bid;
