  insert into public.opportunities (brand_id, title, application_url, source_url, status, opportunity_type) values (bid, 'UpCircle Beauty Affiliate Program (CJ Affiliate)', 'https://getlasso.co/affiliate/upcircle-beauty/', null, 'unverified', 'ugc');
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://getlasso.co/affiliate/upcircle-beauty/', 'directory', 'affiliate_program', 'Lasso''s UpCircle Beauty program page lists a 5% per sale commission rate and a 14-day cookie duration, and the page''s join links route to signup.cj.com, confirming the program runs on CJ Affiliate. The brand''s own US storefront describes UpCircle as the UK''s #1 upcycled beauty brand, a certified B Corp stocked in over 55 countries.', 'publicly_reported', now());
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://getlasso.co/affiliate/upcircle-beauty/', 'directory', 'commission_cap', 'No earnings-cap statement is published for this program, so commission_cap is recorded as unknown (not uncapped). No absolute creator counts are published, so creator_saturation stays unknown.', 'publicly_reported', now());
  insert into public.brand_scores (brand_id, niche_fit, ugc_evidence, compensation, contact_access, opportunity_availability, credibility, explanation) values (bid, 22, 12, 9, 8, 8, 4, '{"compensation": "A published 5% rate on CJ Affiliate; modest percentage and a short 14-day cookie keep compensation mid-range.", "contact_access": "Self-serve network application through CJ Affiliate; no public brand partnerships email.", "credibility": "Certified B Corp with 25,000+ five-star reviews claimed on its own storefront and distribution in over 55 countries.", "niche_fit": "Upcycled, vegan, cruelty-free skincare gives clean-beauty creators a strong story angle beyond the product itself.", "opportunity_availability": "Open network enrollment on CJ Affiliate with no published follower minimum.", "ugc_evidence": "An active network affiliate program for a content-friendly sustainability brand; no dedicated creator program page on the brand''s own site."}'::jsonb);
  insert into public.brands (name, website, description, country, status) values ('Kopari Beauty', 'https://koparibeauty.com', 'San Diego clean beauty brand founded in 2015, built on coconut-powered skin and body care (body scrubs, body oils, SPF and deodorant). Creators reach it through its Sovrn Commerce merchant listing; the brand publishes no creator or affiliate program on its own pages and no commission rate could be verified.', null, 'published') returning id into bid;
  insert into public.brand_categories (brand_id, category_id, is_primary) values (bid, (select id from public.categories where slug = 'beauty'), true);
  insert into public.affiliate_programs (brand_id, network, commission_rate, commission_notes, application_url, status, last_checked_at) values (bid, 'Sovrn Commerce', null, 'Commission cap: not stated in any published source found — needs review. Creator saturation: unknown (see evidence). Rate as reported by https://merchants.sovrn.com/merchants/86932/kopari-beauty-affiliate-program.', 'https://merchants.sovrn.com/merchants/86932/kopari-beauty-affiliate-program', 'needs_review', now());
  insert into public.opportunities (brand_id, title, application_url, source_url, status, opportunity_type) values (bid, 'Kopari Beauty Affiliate Program (Sovrn Commerce)', 'https://merchants.sovrn.com/merchants/86932/kopari-beauty-affiliate-program', null, 'unverified', 'ugc');
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://merchants.sovrn.com/merchants/86932/kopari-beauty-affiliate-program', 'affiliate_network', 'affiliate_program', 'Sovrn Commerce hosts a Kopari Beauty merchant listing through which publishers can monetize Kopari content; the listing itself states that Kopari''s current participation, commission rates and eligibility requirements could not be independently verified, so commission_rate is recorded as null and availability must be confirmed inside Sovrn.', 'publicly_reported', now());
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://usesnippet.app/pr-emails/kopari', 'directory', 'commission_cap', 'A November 13, 2026 check of Kopari''s own pages found no PR email, no creator program and no affiliate program published by the brand — the Sovrn network listing is the only route in. No cap statement is published anywhere, so commission_cap is unknown (not uncapped), and no absolute creator counts are published, so creator_saturation stays unknown.', 'needs_review', now());
  insert into public.brand_scores (brand_id, niche_fit, ugc_evidence, compensation, contact_access, opportunity_availability, credibility, explanation) values (bid, 23, 13, 6, 6, 6, 5, '{"compensation": "No rate could be verified from any published source \u2014 the network listing itself flags its figures as unverified \u2014 so the rate is null and compensation scores low.", "contact_access": "Network listing only; the brand publishes no PR email, creator form or partnerships contact on its own pages.", "credibility": "Well-established clean beauty brand founded in 2015 in San Diego, widely retailed in the US.", "niche_fit": "Coconut-based body care, SPF and deodorant are staple clean-beauty UGC categories with year-round content demand.", "opportunity_availability": "Joining Sovrn is open, but Kopari''s merchant availability and terms must be confirmed inside the network first.", "ugc_evidence": "The route in is a commerce network listing rather than a creator program; UGC evidence rests on the brand''s long history of creator-friendly clean beauty positioning."}'::jsonb);
  insert into public.brands (name, website, description, country, status) values ('ColourPop', 'https://colourpop.com', 'California-born color cosmetics brand famous for affordable, trend-led makeup and a social-first launch model. Its affiliate program runs on Impact; published rate figures conflict widely across directories (0.8–4%, 1–5%, up to 6%, flat 6% and up to 5–10% all appear), so no single rate is recorded.', null, 'published') returning id into bid;
  insert into public.brand_categories (brand_id, category_id, is_primary) values (bid, (select id from public.categories where slug = 'beauty'), true);
  insert into public.affiliate_programs (brand_id, network, commission_rate, commission_notes, application_url, status, last_checked_at) values (bid, 'Impact', null, 'Commission cap: not stated in any published source found — needs review. Creator saturation: unknown (see evidence). Rate as reported by https://linkclicky.com/affiliate-program/colourpop/.', 'https://linkclicky.com/affiliate-program/colourpop/', 'needs_review', now());
  insert into public.opportunities (brand_id, title, application_url, source_url, status, opportunity_type) values (bid, 'ColourPop Affiliate Program (Impact)', 'https://linkclicky.com/affiliate-program/colourpop/', null, 'unverified', 'ugc');
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://linkclicky.com/affiliate-program/colourpop/', 'directory', 'affiliate_program', 'LinkClicky lists the ColourPop affiliate program on the Impact platform at 1–5% per sale; UpPromote''s directory likewise states ColourPop primarily uses Impact (Impact Radius) for affiliate management, with sub-networks such as FlexOffers and Admitad as alternate routes.', 'publicly_reported', now());
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://getlasso.co/affiliate/colourpop/', 'directory', 'commission_rate_conflict', 'Published ColourPop rates conflict across sources: Lasso lists 0.8–4% per sale with a 7-day cookie, LinkClicky lists 1–5%, UpPromote lists up to 6%, prosociate lists a flat 6%, and Shopper lists up to 5–10%. With no settleable figure, commission_rate is recorded as null. No earnings-cap statement is published, so commission_cap is unknown (not uncapped), and no absolute creator counts are published, so creator_saturation stays unknown.', 'needs_review', now());
  insert into public.brand_scores (brand_id, niche_fit, ugc_evidence, compensation, contact_access, opportunity_availability, credibility, explanation) values (bid, 27, 17, 7, 7, 8, 5, '{"compensation": "A commission program on Impact is confirmed, but published figures conflict too widely to record a rate, so the rate is null and compensation scores low.", "contact_access": "Network application via Impact only; the brand publishes no creator contact or program page of its own.", "credibility": "One of the best-known US affordable makeup brands, operating for over a decade with nationwide retail distribution.", "niche_fit": "Trend-led, low-price color cosmetics are arguably the highest-volume makeup UGC category \u2014 swatches, dupes and launch reviews.", "opportunity_availability": "Open application on Impact; short reported cookie windows (7 days) temper the opportunity.", "ugc_evidence": "ColourPop built its brand on social-first launches and creator content; the Impact program is the monetizable route into that ecosystem."}'::jsonb);
  insert into public.brands (name, website, description, country, status) values ('Milani Cosmetics', 'https://milanicosmetics.com', 'Los Angeles drugstore color cosmetics brand founded over 20 years ago, known for luxury-positioned makeup at mass prices. Its affiliate program runs through Rakuten Advertising; published rate figures conflict (3%, up to 2.4%, up to 1.44% and up to 12% all appear), so no single rate is recorded.', null, 'published') returning id into bid;
