  insert into public.opportunities (brand_id, title, application_url, source_url, status, opportunity_type) values (bid, 'Milani Cosmetics Affiliate Program (Rakuten Advertising)', 'https://getlasso.co/affiliate/milani/', null, 'unverified', 'ugc');
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://getlasso.co/affiliate/milani/', 'directory', 'affiliate_program', 'Lasso lists the Milani affiliate program at 3% per sale with a 14-day cookie, and Lasso''s makeup programs roundup names Rakuten Advertising as Milani''s affiliate network with a $50 payout threshold.', 'publicly_reported', now());
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://www.shopper.com/partnerships/milanicosmetics-com-affiliate-program', 'directory', 'commission_rate_conflict', 'Published Milani rates conflict across sources: Lasso lists 3%, Shopper lists up to 2.4%, Takeads lists up to 1.44% for Milani Cosmetics US, and a 2026 makeup roundup claims up to 12%. With no settleable figure, commission_rate is recorded as null. No earnings-cap statement is published, so commission_cap is unknown (not uncapped), and no absolute creator counts are published, so creator_saturation stays unknown.', 'needs_review', now());
  insert into public.brand_scores (brand_id, niche_fit, ugc_evidence, compensation, contact_access, opportunity_availability, credibility, explanation) values (bid, 25, 14, 7, 7, 8, 5, '{"compensation": "A network program is confirmed, but the published rate figures conflict too widely to record one, so the rate is null and compensation scores low.", "contact_access": "Network application via Rakuten Advertising; the brand works with creators through PR gifting but publishes no partnerships email.", "credibility": "Market-leading US drugstore cosmetics brand with over 20 years of trading and nationwide retail presence.", "niche_fit": "Affordable, highly pigmented makeup is a core drugstore-beauty UGC category \u2014 reviews, dupes and wear tests.", "opportunity_availability": "Open network application; the brand is also reported to gift creators from around 500 followers, widening the entry route.", "ugc_evidence": "A live affiliate program plus an active creator gifting practice reported by creator directories; no dedicated creator program page of its own."}'::jsonb);
  insert into public.brands (name, website, description, country, status) values ('Mylee', 'https://www.mylee.co.uk', 'British at-home nail brand launched in 2014, built around gel polish kits, nail colors and waxing products that promise salon results at home. Its UK affiliate programme runs on Awin: 5% commission on new-customer sales and 3% on existing-customer sales, a 30-day cookie, and a published affiliate team email.', null, 'published') returning id into bid;
