  insert into public.affiliate_programs (brand_id, network, commission_rate, commission_notes, application_url, status, last_checked_at) values (bid, 'Awin', 5, 'Commission cap: not stated in any published source found — needs review. Creator saturation: unknown (see evidence). Rate as reported by https://ui.awin.com/merchant-profile/18386?setLocale=sv_SE.', 'https://ui.awin.com/merchant-profile/18386?setLocale=sv_SE', 'needs_review', now());
  insert into public.opportunities (brand_id, title, application_url, source_url, status, opportunity_type) values (bid, 'Mylee Affiliate Programme (Awin)', 'https://ui.awin.com/merchant-profile/18386?setLocale=sv_SE', null, 'unverified', 'ugc');
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://ui.awin.com/merchant-profile/18386?setLocale=sv_SE', 'network_profile', 'affiliate_program', 'Mylee''s official Awin merchant profile states its standard commission rates — 5% on new-customer sales and 3% on existing-customer sales, with no commission on delivery costs or gift voucher sales — plus a 30-day cookie, exclusive affiliate discounts and promotions, and the Mylee Affiliate Team contact email Nnenna@hsnf.co.uk. The recorded rate of 5 is the published new-customer rate.', 'verified', now());
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://ui.awin.com/merchant-profile/18386?setLocale=sv_SE', 'network_profile', 'commission_cap', 'The Awin profile contains no statement about an earnings cap or limit, so commission_cap is recorded as unknown (not uncapped). No absolute creator counts are published, so creator_saturation stays unknown.', 'verified', now());
  insert into public.brand_scores (brand_id, niche_fit, ugc_evidence, compensation, contact_access, opportunity_availability, credibility, explanation) values (bid, 22, 13, 9, 12, 8, 4, '{"compensation": "Published 5% new-customer and 3% existing-customer rates with a 30-day cookie; modest percentages keep compensation mid-range.", "contact_access": "A named affiliate team email is published on the official Awin profile, on top of standard network application.", "credibility": "British nail brand trading since 2014 with a complete official network profile and an established online community.", "niche_fit": "At-home gel nails are a strong tutorial and transformation UGC niche; the range is narrower than full-line beauty brands.", "opportunity_availability": "Open application on Awin with affiliate-exclusive promotions and a regular affiliate newsletter.", "ugc_evidence": "An active network programme for a tutorial-friendly product category; no dedicated creator program page on the brand''s own site."}'::jsonb);
  insert into public.brands (name, website, description, country, status) values ('ICONIC London', 'https://us.iconiclondoninc.com', 'UK-born makeup brand whose US ICONIC Insiders program gives approved creators a personal storefront on its own site: earn commissions on qualifying purchases made through the storefront within a 14-day window, plus discounts, free product and bonus incentives, paid monthly via Tremendous. Eligibility requires US residence, 18+, and at least one post per week on Instagram or TikTok; the commission percentage sits in an Exhibit B chart that does not publish a readable rate in the terms text.', null, 'published') returning id into bid;
  insert into public.brand_categories (brand_id, category_id, is_primary) values (bid, (select id from public.categories where slug = 'beauty'), true);
  insert into public.affiliate_programs (brand_id, network, commission_rate, commission_notes, application_url, status, last_checked_at) values (bid, 'In-house (ICONIC Insiders via LoudCrowd)', null, 'Commission cap: not stated in any published source found — needs review. Creator saturation: unknown (see evidence). Rate as reported by https://us.iconiclondoninc.com/pages/iconic-insiders-terms.', 'https://us.iconiclondoninc.com/pages/iconic-insiders', 'needs_review', now());
  insert into public.opportunities (brand_id, title, application_url, source_url, status, opportunity_type) values (bid, 'ICONIC Insiders Creator Program', 'https://us.iconiclondoninc.com/pages/iconic-insiders', null, 'unverified', 'ugc');
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://us.iconiclondoninc.com/pages/iconic-insiders-terms', 'brand_site', 'creator_program_terms', 'ICONIC London''s official ICONIC Insiders Terms & Conditions describe its own creator program (administered through LoudCrowd, payments via Tremendous): participants build a personalized storefront on us.iconiclondoninc.com and earn commissions on qualifying purchases made through it within 14 days of the visit, paid on the first business day of each month. Eligibility: US residents 18+ posting at least once a week on Instagram or TikTok, with admission at the brand''s discretion on brand fit.', 'verified', now());
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://us.iconiclondoninc.com/pages/iconic-insiders-terms', 'brand_site', 'commission_cap', 'The terms set commission rates only by reference to an Exhibit B incentives chart whose percentage does not appear in the readable terms text, and they contain no earnings-cap statement, so commission_rate is recorded as null and commission_cap as unknown (not uncapped). No absolute creator counts are published, so creator_saturation stays unknown.', 'verified', now());
  insert into public.brand_scores (brand_id, niche_fit, ugc_evidence, compensation, contact_access, opportunity_availability, credibility, explanation) values (bid, 25, 17, 8, 8, 7, 5, '{"compensation": "Commissions, discounts, free product and bonuses are all in the published terms, but the actual percentage is not readable from published sources, so the rate is null and compensation scores low.", "contact_access": "A dedicated application page and full published terms on the brand''s own domain; no public email.", "credibility": "Established UK makeup brand with a US storefront and complete, lawyer-grade program terms.", "niche_fit": "Glow-focused makeup (highlighters, setting sprays, brushes) is proven beauty UGC material.", "opportunity_availability": "Application is open but admission is discretionary, US-only, and requires at least one post per week on Instagram or TikTok.", "ugc_evidence": "A purpose-built creator storefront program with content requirements, style guides and usage licensing \u2014 among the strongest dedicated UGC structures in this batch."}'::jsonb);
  insert into public.brands (name, website, description, country, status) values ('Squaremouth', 'https://www.squaremouth.com', 'America''s largest travel insurance comparison marketplace, letting travellers quote and buy 100+ policies from 20 top insurers in one place. Its own affiliate program is open to anyone with no minimum commitment, pays commission on every referred policy sale through a 60-day cookie, and states explicitly that it does not cap earnings (non-licensed referrers earn up to $50 per sale).', 'United States', 'published') returning id into bid;
  insert into public.brand_categories (brand_id, category_id, is_primary) values (bid, (select id from public.categories where slug = 'travel'), true);
  insert into public.brand_contacts (brand_id, contact_type, email, contact_url, source_url, verification_status, last_verified_at) values (bid, 'partnerships', 'affiliates@squaremouth.com', null, 'https://www.squaremouth.com/about/affiliates', 'verified', now());
  insert into public.affiliate_programs (brand_id, network, commission_rate, commission_notes, application_url, status, last_checked_at) values (bid, 'Brand direct', null, 'Commission cap: UNCAPPED — stated in the program terms (see evidence). Creator saturation: unknown (see evidence). Rate as reported by https://www.squaremouth.com/about/affiliates.', 'https://www.squaremouth.com/about/affiliates', 'needs_review', now());
  insert into public.opportunities (brand_id, title, application_url, source_url, status, opportunity_type) values (bid, 'Squaremouth Travel Insurance Affiliate Program', 'https://www.squaremouth.com/about/affiliates', 'https://www.squaremouth.com/about/affiliates', 'unverified', 'ugc');
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://www.squaremouth.com/about/affiliates', 'official_program_page', 'commission_cap', 'Official affiliate page FAQ, ''Is There A Limit To How Much I Can Make?'': ''Squaremouth does not set a cap on your potential earnings. The more you refer, the more you can make. Non-licensed referrers can make up to $50 per sale. Licensed referrers may qualify for a volume-based commission structure.'' The page also lists ''No minimum commitments and no cap on earning potential'' as a program benefit.', 'verified', now());
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://www.squaremouth.com/about/affiliates', 'official_program_page', 'affiliate_program', 'Program mechanics from the official page: free to join, anyone eligible with no minimum commitments or qualifications, sign-up in minutes with same-day earning, 60-day cookie lifetime, real-time reporting dashboard, payment by ACH direct deposit once accrued credits exceed $50, paid within 45 days after month-end. The page names small social media influencers, bloggers and independent creators with a travel audience as partners. No percentage commission rate is published on the page, so commission_rate is null.', 'verified', now());
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://www.squaremouth.com/about/affiliates', 'official_program_page', 'contact', 'The official page gives the affiliate team email affiliates@squaremouth.com for account structuring questions, and shows the company address in Summit, NJ.', 'verified', now());
  insert into public.brand_scores (brand_id, niche_fit, ugc_evidence, compensation, contact_access, opportunity_availability, credibility, explanation) values (bid, 26, 14, 15, 13, 9, 5, '{"compensation": "Explicit no-cap statement on the brand''s own page (''does not set a cap on your potential earnings''); held below maximum because no percentage rate is published and non-licensed referrers are limited to $50 per individual sale.", "contact_access": "A named affiliate-team email (affiliates@squaremouth.com) is published on the official program page.", "credibility": "20+ years in business, describes itself as America''s largest travel insurance marketplace, 4.9/5 from 55,204 ratings shown on the page.", "niche_fit": "Travel insurance is a natural add-on for travel creators selling trips, itineraries and travel-safety content.", "opportunity_availability": "Anyone can join with no minimum commitments or qualifications, sign-up in minutes and same-day earning.", "ugc_evidence": "The official page explicitly names small social media influencers, bloggers and independent creators as partners, though the product is a quote widget/link rather than physical-product UGC."}'::jsonb);
  insert into public.brands (name, website, description, country, status) values ('Suunto', 'https://us.suunto.com', 'Finnish sports-watch and dive-computer brand for runners, triathletes and outdoor athletes, with average order values above $300. Its affiliate program pays a 10% base commission (top performers up to 15% with brand approval) on confirmed sales, with a 30-day cookie and monthly payouts, and explicitly welcomes creators, bloggers and social media partners.', null, 'published') returning id into bid;
  insert into public.brand_categories (brand_id, category_id, is_primary) values (bid, (select id from public.categories where slug = 'fitness'), true);
  insert into public.brand_contacts (brand_id, contact_type, email, contact_url, source_url, verification_status, last_verified_at) values (bid, 'partnerships', 'affiliate@suunto.com', null, 'https://us.suunto.com/pages/suunto-affiliate-program', 'verified', now());
  insert into public.affiliate_programs (brand_id, network, commission_rate, commission_notes, application_url, status, last_checked_at) values (bid, 'Brand direct (via affiliate platforms, unnamed on page)', 10, 'Commission cap: not stated in any published source found — needs review. Creator saturation: unknown (see evidence). Rate as reported by https://us.suunto.com/pages/suunto-affiliate-program.', 'https://us.suunto.com/pages/suunto-affiliate-program', 'needs_review', now());
  insert into public.opportunities (brand_id, title, application_url, source_url, status, opportunity_type) values (bid, 'Suunto Affiliate Program', 'https://us.suunto.com/pages/suunto-affiliate-program', 'https://us.suunto.com/pages/suunto-affiliate-program', 'unverified', 'ugc');
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://us.suunto.com/pages/suunto-affiliate-program', 'official_program_page', 'affiliate_program', 'Official US program page FAQ, ''How much can I earn?'': ''Base commission starts at 10%. Top-performing affiliates earn up to 15% with brand approval.'' The 15% is a rate ceiling for approved top performers, not the base rate; the page also states average order value above $300, a 30-day cookie window, monthly payouts and free joining. No earnings-cap statement appears anywhere on the page, so commission_cap is unknown.', 'verified', now());
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://us.suunto.com/pages/suunto-affiliate-program', 'official_program_page', 'creator_program', 'The page says ''Anyone. We welcome creators, publishers, bloggers, and social media partners'' (all applications reviewed), sign-up is via ''one of our affiliate platforms'' (the platforms are not named on the page), and support is via affiliate@suunto.com.', 'verified', now());
  insert into public.brand_scores (brand_id, niche_fit, ugc_evidence, compensation, contact_access, opportunity_availability, credibility, explanation) values (bid, 26, 13, 15, 12, 8, 5, '{"compensation": "10% base commission on an average order value above $300 is strong per-sale pay; the up-to-15% figure is a ceiling for approved top performers and no cap statement is published.", "contact_access": "A dedicated affiliate support email (affiliate@suunto.com) is published on the official page.", "credibility": "Long-established premium sports-watch brand with a global retail presence.", "niche_fit": "GPS watches are core gear for running, triathlon and outdoor fitness creators.", "opportunity_availability": "Open to anyone with applications reviewed for alignment; free to join.", "ugc_evidence": "Creators, bloggers and social media partners are explicitly welcomed, though the program is link/code based rather than a structured UGC campaign program."}'::jsonb);
  insert into public.brands (name, website, description, country, status) values ('437', 'https://shop437.com', 'Social-media-first luxe activewear and swim brand whose styles have been worn by major Instagram celebrities and whose content is mostly user-generated. Its Awin affiliate program pays 10% commission on net sales with a 30-day cookie, monthly payments and real-time reporting; applications are reviewed and coupon/deal sites are not allowed.', null, 'published') returning id into bid;
  insert into public.brand_categories (brand_id, category_id, is_primary) values (bid, (select id from public.categories where slug = 'fitness'), true);
  insert into public.brand_contacts (brand_id, contact_type, email, contact_url, source_url, verification_status, last_verified_at) values (bid, 'partnerships', 'careers@shop437.com', null, 'https://ui.awin.com/merchant-profile/29465?setLocale=da_DK', 'needs_review', null);
  insert into public.affiliate_programs (brand_id, network, commission_rate, commission_notes, application_url, status, last_checked_at) values (bid, 'Awin', 10, 'Commission cap: not stated in any published source found — needs review. Creator saturation: unknown (see evidence). Rate as reported by https://ui.awin.com/merchant-profile/29465?setLocale=da_DK.', 'https://ui.awin.com/merchant-profile/29465?setLocale=da_DK', 'needs_review', now());
  insert into public.opportunities (brand_id, title, application_url, source_url, status, opportunity_type) values (bid, '437 Affiliate Program (Awin)', 'https://ui.awin.com/merchant-profile/29465?setLocale=da_DK', 'https://ui.awin.com/merchant-profile/29465?setLocale=da_DK', 'unverified', 'ugc');
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://ui.awin.com/merchant-profile/29465?setLocale=da_DK', 'network_profile', 'affiliate_program', 'Official Awin merchant profile for 437 (US): ''We offer a 10% commission on net sales, excluding shipping, taxes and returns'', 30-day cookie/conversion window, payments every 30 days, real-time reporting; blogs/sites/publications are reviewed for approval and coupons, discounts, deals and cashback sites are not allowed. No earnings-cap statement is published, so commission_cap is unknown.', 'verified', now());
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://ui.awin.com/merchant-profile/29465?setLocale=da_DK', 'network_profile', 'ugc_collab', 'The Awin profile describes 437 as ''a social media-first brand'' and states ''Most of our content is user-generated as we believe they are the most powerful marketers'', inviting publishers to ''put in a good word for us on your platform and earn money while you''re at it''. Affiliate management contact given as careers@shop437.com.', 'verified', now());
  insert into public.brand_scores (brand_id, niche_fit, ugc_evidence, compensation, contact_access, opportunity_availability, credibility, explanation) values (bid, 25, 17, 14, 10, 7, 4, '{"compensation": "Flat 10% on net sales via Awin is a solid, clearly published rate; no cap statement is published.", "contact_access": "An affiliate management email (careers@shop437.com) is published on the Awin profile, though it is a general careers address rather than a dedicated partnerships inbox.", "credibility": "Well-known social-first activewear label worn by major celebrities, but a smaller company than the global sportswear majors.", "niche_fit": "Activewear and swim are core fitness/fashion creator categories and the brand is built around social content.", "opportunity_availability": "Applications are reviewed for approval and coupon/deal/cashback publishers are excluded, which narrows who can join.", "ugc_evidence": "The brand states most of its content is user-generated and explicitly frames creators as its marketers \u2014 strong UGC evidence."}'::jsonb);
  insert into public.brands (name, website, description, country, status) values ('Glamourange', 'https://glamourange.com', 'Luxury-fashion retailer focused on sunglasses, eyewear and tailored apparel, running a global influencer/ambassador affiliate program. Commission is tiered by audience size — 10% for nano creators (400–10K followers) up to 25% for mega influencers, 30% for existing customers and 35% for brand ambassadors — paid via PayPal. Its ''no maximum'' wording covers the number of referrals, not an earnings cap, so the cap is honestly unknown.', null, 'published') returning id into bid;
  insert into public.brand_categories (brand_id, category_id, is_primary) values (bid, (select id from public.categories where slug = 'fashion'), true);
  insert into public.affiliate_programs (brand_id, network, commission_rate, commission_notes, application_url, status, last_checked_at) values (bid, 'Brand direct', 10, 'Commission cap: not stated in any published source found — needs review. Creator saturation: unknown (see evidence). Rate as reported by https://glamourange.com/en-gh/pages/faq-frequently-asked-questions-glamourange-affiliate-program.', 'https://glamourange.com/en-gh/pages/faq-frequently-asked-questions-glamourange-affiliate-program', 'needs_review', now());
  insert into public.opportunities (brand_id, title, application_url, source_url, status, opportunity_type) values (bid, 'Glamourange Influencer / Ambassador Affiliate Program', 'https://glamourange.com/en-gh/pages/faq-frequently-asked-questions-glamourange-affiliate-program', 'https://glamourange.com/en-gh/pages/faq-frequently-asked-questions-glamourange-affiliate-program', 'unverified', 'ugc');
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://glamourange.com/en-gh/pages/faq-frequently-asked-questions-glamourange-affiliate-program', 'official_program_page', 'affiliate_program', 'Official affiliate FAQ commission table: Tier 1 Nano influencers/inspirers (400–10K followers) 10%, Tier 2 Micro (10K–100K) 15%, Tier 3 Macro (100K–1M) 20%, Tier 4 Mega (1M+) 25%, Tier 5 existing customers 30%, Tier 6 brand ambassadors 35%, Tier 7 blogs/YouTube/websites/podcasts/print 15%. The recorded 10% is the starting social-creator tier.', 'verified', now());
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://glamourange.com/en-gh/pages/faq-frequently-asked-questions-glamourange-affiliate-program', 'official_program_page', 'commission_cap', 'The FAQ says ''No maximum number of referrals you can refer. We want you to earn more money'' — a statement about referral COUNT, not an earnings cap, so per the directory standard commission_cap stays unknown. Program is free and global, applications reviewed in 1–5 business days on follower and engagement metrics, commissions paid by direct deposit to PayPal.', 'verified', now());
  insert into public.brand_scores (brand_id, niche_fit, ugc_evidence, compensation, contact_access, opportunity_availability, credibility, explanation) values (bid, 23, 16, 15, 4, 8, 3, '{"compensation": "10% starting rate for nano creators rising to 35% for ambassadors is generous on paper; no earnings-cap statement is published (only a no-maximum-referrals statement).", "contact_access": "No partnerships email is published on the FAQ page \u2014 contact is via a website form only.", "credibility": "Small, little-known luxury retailer; the fetched FAQ is served from the brand''s Ghana locale and independent track record is thin.", "niche_fit": "Sunglasses and fashion outfits are natural fashion-creator content, though the catalogue is narrower than full-range fashion brands.", "opportunity_availability": "Free and global with a low 400-follower entry tier, but applications are reviewed on follower and engagement metrics.", "ugc_evidence": "The program is explicitly built for influencers, inspirers and ambassadors promoting on social media, blogs and YouTube."}'::jsonb);
  insert into public.brands (name, website, description, country, status) values ('Stasher', 'https://stasher.com', 'The world''s largest luggage-storage platform, with 10,200+ vetted Stashpoints in hotels and shops across 1,200+ cities, letting travellers store bags for half the price of station lockers. Its affiliate program (run on Tapfiliate) pays 10% recurring commission on bookings with a 30-day cookie, monthly payouts from a £50 threshold, and explicitly lists social media creators among its channels.', null, 'published') returning id into bid;
  insert into public.brand_categories (brand_id, category_id, is_primary) values (bid, (select id from public.categories where slug = 'travel'), true);
  insert into public.affiliate_programs (brand_id, network, commission_rate, commission_notes, application_url, status, last_checked_at) values (bid, 'Brand direct (Tapfiliate)', 10, 'Commission cap: not stated in any published source found — needs review. Creator saturation: unknown (see evidence). Rate as reported by https://tapfiliate.com/offers/stasher-affiliate-program/.', 'https://stasher.tapfiliate.com', 'needs_review', now());
  insert into public.opportunities (brand_id, title, application_url, source_url, status, opportunity_type) values (bid, 'Stasher Affiliate Program', 'https://stasher.tapfiliate.com', 'https://tapfiliate.com/offers/stasher-affiliate-program/', 'unverified', 'ugc');
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://tapfiliate.com/offers/stasher-affiliate-program/', 'official_program_page', 'affiliate_program', 'Stasher''s official program listing on its Tapfiliate portal: ''Commission, 10% Recurring'', cookie duration 30 days, payment monthly via PayPal and bank transfer with a £50 payout threshold, worldwide geography, channels include travel blogs, city guides and ''Social Media Creators''. Join portal is stasher.tapfiliate.com. No earnings-cap statement is published, so commission_cap is unknown.', 'verified', now());
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://stasher.com', 'official_site', 'general', 'The brand''s homepage states 4.94 from 1.5M+ worldwide ratings, 10,200+ Stashpoints, millions of bags stored, and every booking includes insurance cover up to $1,000 per bag (per the program listing).', 'verified', now());
  insert into public.brand_scores (brand_id, niche_fit, ugc_evidence, compensation, contact_access, opportunity_availability, credibility, explanation) values (bid, 24, 13, 13, 4, 9, 4, '{"compensation": "10% recurring commission is fairly paid, but luggage-storage bookings are low-value, so per-sale earnings are small; no cap statement is published.", "contact_access": "No partnerships email is published on the program listing \u2014 joining is self-serve through the Tapfiliate portal.", "credibility": "Established platform: world''s largest luggage-storage network, 1,200+ cities and 1.5M+ ratings at 4.94.", "niche_fit": "A genuinely useful service for travel creators making city guides and travel-hack content.", "opportunity_availability": "Open self-serve sign-up, worldwide, with social media creators an explicitly listed channel.", "ugc_evidence": "Social media creators are a named channel, though much of the program is aimed at hosts, venues and travel blogs."}'::jsonb);
  insert into public.brands (name, website, description, country, status) values ('Novelship', 'https://novelship.com', 'Asia-based marketplace for authentic limited-edition sneakers, streetwear and collectibles. Its affiliate program runs through Impact and is aimed squarely at content creators and influencers: commissions vary by country and customer type up to 5% of the order amount (a ceiling, so no base rate is recorded), with monthly payments, promotional materials and early release information.', null, 'published') returning id into bid;
  insert into public.brand_categories (brand_id, category_id, is_primary) values (bid, (select id from public.categories where slug = 'fashion'), true);
  insert into public.brand_contacts (brand_id, contact_type, email, contact_url, source_url, verification_status, last_verified_at) values (bid, 'partnerships', 'marketing@novelship.com', null, 'https://novelship.com/news/novelship-affiliate-program/', 'verified', now());
  insert into public.affiliate_programs (brand_id, network, commission_rate, commission_notes, application_url, status, last_checked_at) values (bid, 'Impact', null, 'Commission cap: not stated in any published source found — needs review. Creator saturation: unknown (see evidence). Rate as reported by https://novelship.com/news/novelship-affiliate-program/.', 'https://novelship.com/news/novelship-affiliate-program/', 'needs_review', now());
  insert into public.opportunities (brand_id, title, application_url, source_url, status, opportunity_type) values (bid, 'Novelship Affiliate Program', 'https://novelship.com/news/novelship-affiliate-program/', 'https://novelship.com/news/novelship-affiliate-program/', 'unverified', 'ugc');
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://novelship.com/news/novelship-affiliate-program/', 'official_program_page', 'affiliate_program', 'Official program announcement: ''Apply: Sign up through our affiliate portal, Impact'', ''Earn a commission up to 5% of order sale amount for each new successful order'', and FAQ ''Commission rates vary based on countries & customer type from which purchases are made, up to 5% of order sale amount.'' Only a ceiling is published — no base rate — so commission_rate is null. Payments monthly subject to a minimum payout threshold; no earnings-cap statement, so commission_cap is unknown.', 'verified', now());
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://novelship.com/news/novelship-affiliate-program/', 'official_program_page', 'creator_program', 'The page targets ''content creators, influencers, and anyone passionate about sneakers, streetwear, and collectibles'' with a blog, YouTube channel or social presence, offers banners/graphics and early release information, and gives marketing@novelship.com for affiliate inquiries.', 'verified', now());
  insert into public.brand_scores (brand_id, niche_fit, ugc_evidence, compensation, contact_access, opportunity_availability, credibility, explanation) values (bid, 23, 13, 8, 11, 8, 4, '{"compensation": "Only an up-to-5% ceiling is published, varying by country and customer type \u2014 a low and uncertain rate, so no base rate is recorded.", "contact_access": "A marketing email (marketing@novelship.com) is published on the official program page for affiliate inquiries.", "credibility": "Established sneaker marketplace in Asia with an authenticity focus, though less known in the US/EU.", "niche_fit": "Sneakers and streetwear are a strong fashion-creator niche.", "opportunity_availability": "Free to join via Impact with applications reviewed for fit; no sales targets.", "ugc_evidence": "The program explicitly recruits creators, influencers and bloggers and supplies promotional materials."}'::jsonb);
  insert into public.brands (name, website, description, country, status) values ('Atlas Swimwear', 'https://www.atlasswimwear.co', 'Small swimwear brand running a three-tier creator ladder: an open Explorer community tier, an application-only Ambassador tier paying 10% commission on sales through a personal code (ambassadors must buy a suit and post ATLAS content on TikTok/Instagram), and an invite-or-50-sales Voyager sponsorship tier at 15% commission with free product.', null, 'published') returning id into bid;
  insert into public.brand_categories (brand_id, category_id, is_primary) values (bid, (select id from public.categories where slug = 'fashion'), true);
  insert into public.affiliate_programs (brand_id, network, commission_rate, commission_notes, application_url, status, last_checked_at) values (bid, 'Brand direct', 10, 'Commission cap: not stated in any published source found — needs review. Creator saturation: unknown (see evidence). Rate as reported by https://www.atlasswimwear.co/affiliates.html.', 'https://www.atlasswimwear.co/affiliates.html', 'needs_review', now());
  insert into public.opportunities (brand_id, title, application_url, source_url, status, opportunity_type) values (bid, 'Atlas Swimwear Ambassador Program', 'https://www.atlasswimwear.co/affiliates.html', 'https://www.atlasswimwear.co/affiliates.html', 'unverified', 'ugc');
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://www.atlasswimwear.co/affiliates.html', 'official_program_page', 'ambassador_program', 'Official affiliates page: Ambassador tier is application-only; to qualify you must purchase at least one ATLAS bathing suit, actively repost ATLAS videos on TikTok and/or Instagram, create your own ATLAS video and submit a screenshot or DM. Accepted ambassadors get a custom 10%-off follower code and ''10% commission on all sales through your code''. The recorded 10% is this Ambassador rate.', 'verified', now());
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://www.atlasswimwear.co/affiliates.html', 'official_program_page', 'ambassador_program', 'Voyager sponsorship tier (sell 50 bathing suits through your code, or be personally invited) pays ''15% commission on all referred sales'' plus two free bathing suits and 20% off gear. No earnings-cap statement appears on the page, so commission_cap is unknown; no partnerships email is published.', 'verified', now());
  insert into public.brand_scores (brand_id, niche_fit, ugc_evidence, compensation, contact_access, opportunity_availability, credibility, explanation) values (bid, 22, 16, 13, 4, 6, 3, '{"compensation": "10% Ambassador commission rising to 15% at the sponsorship tier is fair for a small brand; no cap statement is published.", "contact_access": "No partnerships email is published \u2014 application is via the website/DM only.", "credibility": "Very small, young swimwear brand with limited public track record.", "niche_fit": "Swimwear is a proven fashion-creator category, though the range is a single product type.", "opportunity_availability": "The earning tier is application-only and requires buying a suit and posting brand content before acceptance, which limits availability.", "ugc_evidence": "The program is built entirely around creator content \u2014 reposting and original TikTok/Instagram videos are explicit requirements."}'::jsonb);
  insert into public.brands (name, website, description, country, status) values ('StockX', 'https://stockx.com', 'The live bid/ask marketplace for sneakers, streetwear, collectibles, watches and handbags. Its affiliate program runs on Impact: 3% on sneakers, streetwear and collectibles for new customers (1% returning) and 4% on watches and handbags for new customers (2% returning), earned on any bid that converts to a sale within 15 days, backed by a dedicated affiliate team.', null, 'published') returning id into bid;
  insert into public.brand_categories (brand_id, category_id, is_primary) values (bid, (select id from public.categories where slug = 'fashion'), true);
  insert into public.affiliate_programs (brand_id, network, commission_rate, commission_notes, application_url, status, last_checked_at) values (bid, 'Impact', 3, 'Commission cap: not stated in any published source found — needs review. Creator saturation: unknown (see evidence). Rate as reported by https://stockx.com/news/stockx-affiliate-program/.', 'https://stockx.com/news/stockx-affiliate-program/', 'needs_review', now());
  insert into public.opportunities (brand_id, title, application_url, source_url, status, opportunity_type) values (bid, 'StockX Affiliate Program', 'https://stockx.com/news/stockx-affiliate-program/', 'https://stockx.com/news/stockx-affiliate-program/', 'unverified', 'ugc');
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://stockx.com/news/stockx-affiliate-program/', 'official_program_page', 'affiliate_program', 'Official StockX program announcement: ''To get started, login or sign up with Impact''; ''Commissions You Earn: Sneakers, Streetwear, & Collectibles: 3% for new customers (first time purchasers), 1% for returning customers. Watches & Handbags: 4% for new customers, 2% for returning customers''; commission is earned on any bid that converts to a sale within 15 days. The recorded 3% is the headline sneakers/streetwear new-customer rate. No earnings-cap statement is published, so commission_cap is unknown.', 'verified', now());
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://stockx.com/news/stockx-affiliate-program/', 'official_program_page', 'affiliate_program', 'The announcement (published 2019-07-09) highlights high average order values, monthly newsletters on top-selling products and a ''Dedicated Affiliate Team for collaboration and assistance''. The affiliate contact email shown on the page could not be read in full, so no contact row is recorded.', 'verified', now());
  insert into public.brand_scores (brand_id, niche_fit, ugc_evidence, compensation, contact_access, opportunity_availability, credibility, explanation) values (bid, 24, 12, 8, 7, 8, 5, '{"compensation": "Rates are low \u2014 3% new / 1% returning on sneakers and streetwear \u2014 partly offset by high average order values; no cap statement is published.", "contact_access": "A dedicated affiliate team is named on the official page, but the contact email could not be read in full, so no email is recorded.", "credibility": "One of the largest and best-known resale marketplaces in sneakers and streetwear.", "niche_fit": "Sneaker and streetwear drops are a core fashion-creator beat with constant new-release content.", "opportunity_availability": "Self-serve sign-up via Impact with a brand-fit review; open to social and media publishers.", "ugc_evidence": "The program is pitched at social and media outlets and supplies creative assets, but it is a link-based affiliate program rather than a UGC campaign program."}'::jsonb);
  insert into public.brands (name, website, description, country, status) values ('RVshare', 'https://rvshare.com', 'The largest US peer-to-peer RV rental marketplace, with 100,000+ listed vehicles and average bookings around $699–$900. Its affiliate program is offered through CJ Affiliate (and Travelpayouts), but published rates conflict across sources — 4% per rental on CJ, 5–7% in one directory, 6.5% on Travelpayouts — so no rate is recorded, only the conflict.', null, 'published') returning id into bid;
  insert into public.brand_categories (brand_id, category_id, is_primary) values (bid, (select id from public.categories where slug = 'travel'), true);
  insert into public.affiliate_programs (brand_id, network, commission_rate, commission_notes, application_url, status, last_checked_at) values (bid, 'CJ Affiliate', null, 'Commission cap: not stated in any published source found — needs review. Creator saturation: unknown (see evidence). Rate as reported by https://commission.academy/blog/best-rv-affiliate-programs/.', 'https://www.travelpayouts.com/blog/rvshare-affiliate-program/', 'needs_review', now());
  insert into public.opportunities (brand_id, title, application_url, source_url, status, opportunity_type) values (bid, 'RVshare Affiliate Program', 'https://www.travelpayouts.com/blog/rvshare-affiliate-program/', 'https://www.travelpayouts.com/blog/rvshare-affiliate-program/', 'unverified', 'ugc');
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://commission.academy/blog/best-rv-affiliate-programs/', 'third_party_directory', 'commission_rate_conflict', 'Commission Academy reports the RVshare program as integrated with Commission Junction (CJ Advertiser ID 5126501), paying ''4% per referred RV Rental Order'' plus ''$7 per referred New RV Listing'', with 30-day (rental) and 45-day (listing) cookie life and a $900 average order value.', 'publicly_reported', now());
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://www.travelpayouts.com/blog/rvshare-affiliate-program/', 'third_party_directory', 'commission_rate_conflict', 'Travelpayouts, which also carries the RVshare offer (US travel projects only, advertiser pre-approval required), publishes a different figure: ''Affiliates can earn 6.5% commission on each completed booking (after check-in) and $12 for every new listing of an RV'', with a $699 average booking value. A third directory (Lasso) reports 5–7% per order. Because the published rates conflict (4% vs 5–7% vs 6.5%), commission_rate is null. No earnings-cap statement was found, so commission_cap is unknown.', 'publicly_reported', now());
  insert into public.brand_scores (brand_id, niche_fit, ugc_evidence, compensation, contact_access, opportunity_availability, credibility, explanation) values (bid, 24, 11, 10, 4, 7, 5, '{"compensation": "High booking values ($699\u2013$900 average) make even a mid-single-digit rate meaningful, but published rates conflict across sources (4% / 5\u20137% / 6.5%), so no rate is recorded and compensation is scored cautiously.", "contact_access": "No affiliate partnerships email was verified from a fetched source.", "credibility": "The largest RV rental marketplace in the US with 100,000+ vehicles and millions of nights booked.", "niche_fit": "RV and road-trip content is a strong, growing travel-creator niche.", "opportunity_availability": "Available via CJ Affiliate and Travelpayouts, but the advertiser requires pre-approval and the Travelpayouts offer is limited to US travel projects.", "ugc_evidence": "The program targets travel publishers and bloggers; creator-specific UGC campaigns are not evidenced."}'::jsonb);
  insert into public.brands (name, website, description, country, status) values ('Mountain Warehouse', 'https://www.mountainwarehouse.com', 'Large UK outdoor retailer selling own-brand clothing and gear for camping, hiking, running, skiing and travel at budget prices. It runs territory affiliate programs through networks including Awin and Rakuten with a 30-day cookie and manual application approval, but its own affiliates page publishes no rate and third-party figures conflict (around 4% in recent directories vs 8.4% in an older listing), so no rate is recorded.', 'United Kingdom', 'published') returning id into bid;
  insert into public.brand_categories (brand_id, category_id, is_primary) values (bid, (select id from public.categories where slug = 'fashion'), true);
  insert into public.affiliate_programs (brand_id, network, commission_rate, commission_notes, application_url, status, last_checked_at) values (bid, 'Awin / Rakuten Advertising', null, 'Commission cap: not stated in any published source found — needs review. Creator saturation: unknown (see evidence). Rate as reported by https://www.mountainwarehouse.com/us/affiliates/.', 'https://www.mountainwarehouse.com/us/affiliates/', 'needs_review', now());
  insert into public.opportunities (brand_id, title, application_url, source_url, status, opportunity_type) values (bid, 'Mountain Warehouse Affiliate Program', 'https://www.mountainwarehouse.com/us/affiliates/', 'https://www.mountainwarehouse.com/us/affiliates/', 'unverified', 'ugc');
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://www.mountainwarehouse.com/us/affiliates/', 'official_program_page', 'affiliate_program', 'Official US affiliates page: the program is aimed at sites covering camping, cycling, outdoors, running, skiing, swimming, yoga, walking and travelling; it promises ''High commission rates on every sale you make'' without publishing a figure, a 30-day cookie length, and notes ''all affiliate applications are manually approved'' and that affiliates join only the territory program matching their audience. No earnings-cap statement is published, so commission_cap is unknown.', 'verified', now());
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://getlasso.co/affiliate/mountain-warehouse/', 'third_party_directory', 'commission_rate_conflict', 'Directories conflict on the rate: Lasso reports 4% per sale with a 30-day cookie, Shopper reports up to 3.99%, and an older affjumbo listing reports 8.4%. Groupon reports the program runs ''through Rakuten/Linkshare and AWIN''. Because the figures conflict and the brand publishes none, commission_rate is null.', 'publicly_reported', now());
  insert into public.brand_scores (brand_id, niche_fit, ugc_evidence, compensation, contact_access, opportunity_availability, credibility, explanation) values (bid, 23, 10, 9, 4, 7, 5, '{"compensation": "No rate is published by the brand and directory figures conflict (about 4% recently, 8.4% in an older listing), so no rate is recorded and compensation scores low.", "contact_access": "No partnerships email is published on the official affiliates page \u2014 contact is via territory web forms.", "credibility": "One of the UK''s largest outdoor retailers with a long trading history and stores internationally.", "niche_fit": "Affordable outdoor clothing and gear fits fashion, fitness and travel creators making outdoor content.", "opportunity_availability": "Programs run per territory via Awin/Rakuten with manual approval of every application.", "ugc_evidence": "The official page addresses website owners placing banners and text links; there is little evidence of creator-specific UGC work."}'::jsonb);
  insert into public.brands (name, website, description, country, status) values ('PaleoPro', 'https://paleopro.com', 'PaleoPro makes clean, real-food protein products — protein powders and bars with no whey, no soy and no junk ingredients — for paleo and whole-food audiences. Its Creator Partnership Program pays tiered commission plus per-order bonuses on first orders.', 'United States', 'published') returning id into bid;
  insert into public.brand_categories (brand_id, category_id, is_primary) values (bid, (select id from public.categories where slug = 'health'), true);
  insert into public.affiliate_programs (brand_id, network, commission_rate, commission_notes, application_url, status, last_checked_at) values (bid, 'Brand direct', 20, 'Commission cap: UNCAPPED — stated in the program terms (see evidence). Creator saturation: unknown (see evidence). Rate as reported by https://paleopro.com/pages/creator-partnership-program.', 'https://paleopro.com/pages/creator-partnership-program', 'needs_review', now());
  insert into public.opportunities (brand_id, title, application_url, source_url, status, opportunity_type) values (bid, 'PaleoPro Creator Partnership Program', 'https://paleopro.com/pages/creator-partnership-program', 'https://paleopro.com/pages/creator-partnership-program', 'unverified', 'ugc');
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://paleopro.com/pages/creator-partnership-program', 'brand_website', 'affiliate_program', 'PaleoPro''s own Creator Partnership Program page states ''No minimums. No requirements. No cap.'' and shows unlimited earning potential; seven automatic tiers run from 20% commission plus a $5 per-order bonus to 30% plus $10 per order at 10,000+ first orders, with no follower minimum and free joining — the explicit no-cap statement on the brand''s own page is why commission_cap is recorded as uncapped.', 'verified', now());
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://paleopro.com/pages/creator-partnership-program', 'brand_website', 'commission', 'Per the program page, commission rates and per-order bonuses apply to qualifying first-order sales at each tier, tiers advance automatically at order milestones with no renegotiation, and payment details are shared on acceptance; no creator-count data is published, so creator_saturation is unknown.', 'publicly_reported', now());
  insert into public.brand_scores (brand_id, niche_fit, ugc_evidence, compensation, contact_access, opportunity_availability, credibility, explanation) values (bid, 25, 16, 19, 6, 9, 4, '{"compensation": "Verified uncapped on the brand''s own page, with 20% base commission rising to 30% plus per-order bonuses up to $10.", "contact_access": "Application is on the brand''s own site, but no public partnerships email is published.", "credibility": "Established real-food protein brand with a long-running direct storefront.", "niche_fit": "Real-food protein powders and bars sit squarely in the health and paleo creator niche.", "opportunity_availability": "Program is open now, free to join, with no follower minimum and automatic tier progression.", "ugc_evidence": "The brand runs a dedicated creator partnership program with tiered rewards built for content creators."}'::jsonb);
