  insert into public.brands (name, website, description, country, status) values ('Zoma Sleep', 'https://zomasleep.com', 'US mattress brand (Zoma Sleep LLC, Scottsdale, Arizona) selling sports-recovery-focused memory-foam and hybrid mattresses, pillows, adjustable beds and bedding direct through Zomasleep.com. Its affiliate program is built around product reviewers: affiliates receive and test a mattress, publish their review, and earn commission on referred sales through Impact.', 'United States', 'published') returning id into bid;
