  insert into public.opportunities (brand_id, title, application_url, source_url, status, opportunity_type) values (bid, 'Zoma Affiliate Program — earning potential uncapped per official FAQ, paid monthly via Impact, 90-day cookie', 'https://zomasleep.com/affiliates', 'https://zomasleep.com/affiliates', 'unverified', 'ugc');
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://zomasleep.com/affiliates', 'official_site', 'affiliate', 'Official Zoma affiliate page fetched in full: free to join with no startup or maintenance fees, a 90-day cookie duration, creative and marketing assets and dedicated affiliate support; affiliates are paid every month through Impact (the page''s Become an Affiliate button leads to app.impact.com). Its FAQ answers the earnings question directly: ''How much can I earn? The sky''s the limit! Your earning potential is uncapped and is based on your ability to drive purchases to Zomasleep.com.'' The explicit uncapped statement on the brand''s own page makes the commission cap UNCAPPED. The page publishes no percentage rate (''competitive payout terms'', ''earn more as you sell more''), so commission_rate is null.', 'verified', now());
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://zomasleep.com/affiliates', 'official_site', 'creator_program', 'The same official page describes a reviewer workflow: ''After you receive and test your mattress, start publishing your review on your website with your affiliate link'' — a product-seeded review program aimed at content publishers, with last-click attribution inside the 90-day cookie window.', 'verified', now());
  insert into public.brand_scores (brand_id, niche_fit, ugc_evidence, compensation, contact_access, opportunity_availability, credibility, explanation) values (bid, 25, 13, 12, 10, 8, 4, '{"compensation": "Explicit uncapped earnings statement on the brand''s own page and a long 90-day cookie, but no percentage rate is published, so compensation cannot be graded higher", "contact_access": "Impact application linked from the brand''s own affiliate page, plus a published phone number (888-400-8856); no public program email found", "credibility": "Established US mattress brand with BBB profile linked from its own site and national press coverage quoted on the page", "niche_fit": "Mattresses and sleep products are a core home UGC review category, and the athlete-recovery angle gives creators a distinct content hook", "opportunity_availability": "Free Impact registration with no follower minimum published", "ugc_evidence": "The program is structured around seeded product reviews published by affiliates, though it is framed for review sites rather than social-first creators"}'::jsonb);
  insert into public.brands (name, website, description, country, status) values ('Essentia', 'https://myessentia.com', 'Organic mattress and pillow brand (Essentia Organic Mattress - USA, Boca Raton, Florida) selling natural-memory-foam mattresses made with organic latex and plant-based ingredients through MyEssentia.com. Its affiliate program gives publishers a dashboard, banners, social assets and video to promote the range.', 'United States', 'published') returning id into bid;
