  insert into public.affiliate_programs (brand_id, network, commission_rate, commission_notes, application_url, status, last_checked_at) values (bid, 'Awin', null, 'Commission cap: UNCAPPED — stated in the program terms (see evidence). Creator saturation: unknown (see evidence). Rate as reported by https://myessentia.com/pages/affiliate-program.', 'https://myessentia.com/pages/affiliate-program', 'needs_review', now());
  insert into public.opportunities (brand_id, title, application_url, source_url, status, opportunity_type) values (bid, 'Essentia Affiliate Program — ''no limit to how much you can earn'' per official page, via Awin', 'https://myessentia.com/pages/affiliate-program', 'https://myessentia.com/pages/affiliate-program', 'unverified', 'ugc');
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://myessentia.com/pages/affiliate-program', 'official_site', 'affiliate', 'Official Essentia affiliate page fetched in full: ''Join Essentia''s affiliate program on AWIN to earn when you share!'' — the program provides a dashboard to track real-time performance, banners, social media assets, videos and exclusive offers, and states ''There is no limit to how much you can earn!'' Its FAQ repeats the point: ''What is my commission? Once approved, you will have full access to your affiliate dashboard. Your earning potential is unlimited.'' The explicit no-limit statements on the brand''s own page make the commission cap UNCAPPED. No percentage rate is published on the page (rates sit inside the dashboard), so commission_rate is null. Note: the page''s ''apply here'' link still points to shareasale.com even though the page text names AWIN as the network — the stale link is recorded here and Awin is recorded as the network the brand itself names.', 'verified', now());
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://myessentia.com/pages/affiliate-program', 'official_site', 'general', 'The same official page states joining is free, sites are reviewed manually and approved quickly, coupon/promo sites are not accepted, and trademark/URL bidding is not allowed; the brand''s US address (6510 W Rogers Cir, Boca Raton, FL 33487) and phone (+1-888-752-0335) are published on the page.', 'verified', now());
  insert into public.brand_scores (brand_id, niche_fit, ugc_evidence, compensation, contact_access, opportunity_availability, credibility, explanation) values (bid, 24, 11, 12, 8, 7, 4, '{"compensation": "Explicit ''no limit'' and ''unlimited'' earnings statements on the brand''s own page, but the percentage rate is not published outside the dashboard", "contact_access": "Application linked from the brand''s own page and a phone number published; no public program email found, and the apply link still points to ShareASale while the page names Awin", "credibility": "Long-running organic mattress brand with full program FAQ published on its own storefront", "niche_fit": "Organic mattresses and pillows are a proven home/wellness UGC category with a clear clean-sleep content angle", "opportunity_availability": "Free to join but sites are manually reviewed and coupon/promo sites are excluded", "ugc_evidence": "Publisher program with social media assets and video provided, but framed for websites rather than social-first creators"}'::jsonb);
  insert into public.brands (name, website, description, country, status) values ('Diamond Mattress', 'https://diamondmattress.com', 'US mattress manufacturer selling mattresses, adjustable bases and sleep accessories direct through DiamondMattress.com. Its affiliate program runs through Impact and rewards partners per referred customer, with higher commission rates and cash bonuses for top performers.', 'United States', 'published') returning id into bid;
