  insert into public.opportunities (brand_id, title, application_url, source_url, status, opportunity_type) values (bid, 'Diamond Mattress Affiliate Program — ''no limit to what you can earn'' per official page, via Impact', 'https://diamondmattress.com/pages/affiliate-programs', 'https://diamondmattress.com/pages/affiliate-programs', 'unverified', 'ugc');
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://diamondmattress.com/pages/affiliate-programs', 'official_site', 'affiliate', 'Official Diamond Mattress affiliate page fetched in full: the program is free to join through Impact (the page links to app.impact.com and states ''we use Impact ... as our Affiliate Marketing Network''); affiliates receive all needed creatives and are paid for every referred customer who purchases. Its Growth Potential section states: ''When you partner with Diamond Mattress, you''re joining one of the leaders in a booming industry. There is no limit to what you can earn.'' The explicit no-limit statement on the brand''s own page makes the commission cap UNCAPPED. Rates are tiered (''The more you sell, the higher your comission rates'', plus cash bonuses for top partners) but no percentage is published, so commission_rate is null.', 'verified', now());
  insert into public.brand_scores (brand_id, niche_fit, ugc_evidence, compensation, contact_access, opportunity_availability, credibility, explanation) values (bid, 24, 10, 12, 8, 8, 4, '{"compensation": "Explicit ''no limit to what you can earn'' statement on the brand''s own page with performance rewards and bonuses, but no published percentage rate", "contact_access": "Impact application linked from the brand''s own affiliate page; no public program email found", "credibility": "Established US mattress manufacturer with program terms published on its own storefront", "niche_fit": "Mattresses are a core home UGC review category with high order values", "opportunity_availability": "Free Impact application with no follower minimum published", "ugc_evidence": "Standard publisher program with creatives provided; no creator-specific tier or content program published"}'::jsonb);
  insert into public.brands (name, website, description, country, status) values ('Brentwood Home', 'https://www.brentwoodhome.com', 'California-made mattress and home brand selling mattresses, bedding, pillows, kids'' and pet beds handcrafted in its Los Angeles factory with natural and organic materials, through BrentwoodHome.com. Its affiliate program is managed on Impact and pays commission across the full catalogue, not just mattresses.', 'United States', 'published') returning id into bid;
