  insert into public.opportunities (brand_id, title, application_url, source_url, status, opportunity_type) values (bid, 'Brentwood Home Affiliate Program — mattresses and natural home goods via Impact (published rates conflict at 5%-15%)', 'https://linkclicky.com/affiliate-program/brentwood-home/', 'https://linkclicky.com/affiliate-program/brentwood-home/', 'unverified', 'ugc');
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://linkclicky.com/affiliate-program/brentwood-home/', 'listing', 'affiliate', 'LinkClicky program listing (which reads the network''s published terms): the Brentwood Home affiliate program runs on Impact and pays 5%-8% per sale. CompareEPC''s furniture-program index likewise lists Brentwood Home on Impact at 5%. No earnings-cap statement is published, so the cap is unknown.', 'publicly_reported', now());
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://getlasso.co/affiliate/brentwood-home/', 'listing', 'affiliate', 'Older roundups report a different, historical structure: Lasso lists Brentwood Home at 15% per sale, and mattress-program roundups describe a 15% ShareASale program with a 120-day cookie and $50 payout threshold. Because the published figures conflict (15% on the old ShareASale program vs 5%-8% on the current Impact listings), commission_rate is null with the conflict recorded here; the Impact route is the one current network listings agree on.', 'publicly_reported', now());
  insert into public.brand_scores (brand_id, niche_fit, ugc_evidence, compensation, contact_access, opportunity_availability, credibility, explanation) values (bid, 25, 10, 9, 8, 6, 4, '{"compensation": "Published rates conflict between the historical 15% ShareASale figure and current 5%-8% Impact listings, so no rate can be credited until verified in-network", "contact_access": "Application runs through Impact; no public partnerships email found", "credibility": "Long-running US mattress maker with consistent program listings across networks over many years", "niche_fit": "Mattresses, bedding and pet beds made in California from natural materials give home creators several content angles", "opportunity_availability": "Roundups describe the program as selective/exclusive, with brand fit reviewed before acceptance", "ugc_evidence": "Network publisher program; no dedicated creator page published"}'::jsonb);
  insert into public.brands (name, website, description, country, status) values ('Identity Pet Nutrition', 'https://www.identitypet.com', 'US pet-food brand (Identity Pet Nutrition, LLC, Windsor, Colorado) selling gently cooked and raw-inspired dog and cat foods made with high meat inclusion, through IdentityPet.com. Its Identity Creative Affiliate Program is written specifically for content creators and influencers, who earn commission through personal SafeLinks and single-use customer coupon codes.', 'United States', 'published') returning id into bid;
