  insert into public.opportunities (brand_id, title, application_url, source_url, status, opportunity_type) values (bid, 'Identity Creative Affiliate Program — 15% commission for pet content creators, brand direct ($100 payout threshold)', 'https://www.identitypet.com/pages/identity-creative-creators', 'https://www.identitypet.com/pages/identity-creative-creators', 'unverified', 'ugc');
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://www.identitypet.com/pages/identity-creative-creators', 'official_site', 'affiliate', 'Official Identity Creative Content Creators Affiliate Program terms (effective January 1, 2025) fetched in full: the program is open to ''content creators, influencers, or marketing affiliates with an active online presence''; affiliates earn a 15% commission on qualifying sales through their SafeLink (15% of the net purchase amount, excluding taxes, shipping and discounts), with a 30-day cookie, a $59 minimum order, new customers only, and payouts via Trolley monthly at a $100 threshold. Referred customers get 20% off via single-use codes. The terms publish the program contact email customercare@identitypet.com and the company address in Windsor, CO. The terms make no statement about an earnings cap, so the cap is unknown.', 'verified', now());
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://www.identitypet.com/pages/identity-creative-creators', 'official_site', 'creator_program', 'The same official terms are creator-specific throughout: acceptance requires a separate Influencer Agreement, accepted affiliates may receive a free welcome gift valued at up to $175, coupon codes may not be posted to coupon sites or forums, and paid ads redirecting to the brand''s site need prior approval — a managed creator program rather than an open publisher feed.', 'verified', now());
  insert into public.brand_scores (brand_id, niche_fit, ugc_evidence, compensation, contact_access, opportunity_availability, credibility, explanation) values (bid, 24, 16, 14, 11, 6, 3, '{"compensation": "15% of net purchase is a solid pet-food rate, tempered by a $100 payout threshold, a $59 minimum order and new-customer-only qualification", "contact_access": "Application on the brand''s own site plus a published program contact email (customercare@identitypet.com) in the official terms", "credibility": "Full program terms published on the brand''s own storefront; a smaller, younger brand than the pet-food leaders", "niche_fit": "Premium dog and cat food is a core pet UGC category (feeding routines, picky-eater and transition content)", "opportunity_availability": "Application-based and selective \u2014 acceptance is at the brand''s sole discretion and requires signing a separate Influencer Agreement", "ugc_evidence": "The program is explicitly a creator/influencer program with personal links, customisable landing pages and a welcome product gift"}'::jsonb);
  insert into public.brands (name, website, description, country, status) values ('Pet Wellbeing', 'https://petwellbeing.com', 'US pet-supplement brand selling vet-formulated, NASC-certified herbal supplements for dogs and cats (organ support, immunity, digestion, mobility) through PetWellbeing.com. Its affiliate program on Awin has two tracks: a practitioner track for vet clinics and a creator track for pet health advocates, bloggers and social channels.', 'United States', 'published') returning id into bid;
