  insert into public.opportunities (brand_id, title, application_url, source_url, status, opportunity_type) values (bid, 'Pet Wellbeing Affiliate Program — creators earn up to 10% via Awin, 60-day cookie (Merchant ID 87939)', 'https://petwellbeing.com/pages/affiliate-program', 'https://petwellbeing.com/pages/affiliate-program', 'unverified', 'ugc');
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://petwellbeing.com/pages/affiliate-program', 'official_site', 'affiliate', 'Official Pet Wellbeing affiliate page fetched in full: the ''Pet Health Advocates & Creators'' track pays ''Up to 10% commission on every referred sale'' with a 60-day tracking cookie, joining through AWIN (Merchant ID: 87939, published on the page). The separate 20% tier is stated on the same page to be ''exclusive to vet clinics'' under the practitioner track, so the creator rate recorded here is the 10% ceiling of the creator track, following the directory''s rate-ceiling convention. The page makes no statement about an earnings cap, so the cap is unknown.', 'verified', now());
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://petwellbeing.com/pages/affiliate-program', 'official_site', 'creator_program', 'The same official page addresses the creator track directly: ''If you run an established pet wellness blog, community, or social channel, partner with a trusted brand in natural pet health'', with Awin handling tracking, reporting and monthly payment, and the brand citing veterinarian formulation, NASC certification and third-party testing.', 'verified', now());
  insert into public.brand_scores (brand_id, niche_fit, ugc_evidence, compensation, contact_access, opportunity_availability, credibility, explanation) values (bid, 24, 13, 11, 8, 7, 4, '{"compensation": "Up to 10% on the creator track is mid-range for pet supplements; the higher 20% tier is clinics-only and is not credited here", "contact_access": "Awin application with the merchant ID published on the brand''s own page; no public partnerships email found", "credibility": "NASC-certified, vet-formulated brand with its full two-track program published on its own storefront", "niche_fit": "Vet-formulated pet supplements are a proven pet-health UGC category with strong problem/solution content angles", "opportunity_availability": "Standard Awin application, though the page speaks to ''established'' blogs, communities and channels", "ugc_evidence": "A dedicated creator/advocate track is published alongside the clinic track, with a 60-day cookie aimed at considered purchases"}'::jsonb);
