  insert into public.opportunities (brand_id, title, application_url, source_url, status, opportunity_type) values (bid, 'Wild Earth Affiliate Program — plant-based dog food via Impact (flat per-subscription bounty reported, up to $60)', 'https://wildearth.com/pages/veterinarians', 'https://wildearth.com/pages/veterinarians', 'unverified', 'ugc');
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://wildearth.com/pages/veterinarians', 'official_site', 'affiliate', 'Wild Earth''s official affiliate-program page (framed for its veterinary partners) confirms the program mechanics on the brand''s own site: ''Tracking links, tracking QR codes, or custom promo codes are essential for our affiliate program'', partners create tracking links ''within your Impact Radius dashboard'', and ''Contact support@wildearth.com with any questions about our affiliate program'' — the recorded route is the brand''s Impact program, not any marketplace channel. The page publishes no commission figure and no earnings-cap statement, so the rate is null and the cap is unknown.', 'verified', now());
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://runtheaffiliatemarket.com/can-you-make-money-with-the-wild-earth-affiliate-program-review/', 'listing', 'affiliate', 'A program review reports Wild Earth''s affiliate compensation as a flat fee of up to $60 for new subscriptions purchasing certain bag sizes, with a 30-day cookie — a flat bounty rather than a percentage. A coupon-site listing separately claims ''up to 30% commission'', which conflicts with the flat-fee report and is not credited. Because the published compensation is a reported flat bounty with a conflicting percentage claim, commission_rate is null with the flat structure recorded here.', 'publicly_reported', now());
  insert into public.brand_scores (brand_id, niche_fit, ugc_evidence, compensation, contact_access, opportunity_availability, credibility, explanation) values (bid, 23, 11, 9, 9, 7, 3, '{"compensation": "A reported flat bounty of up to $60 per new subscription can pay well per conversion, but the figure is dated and conflicts with a percentage claim elsewhere, so it is graded cautiously", "contact_access": "Program contact email (support@wildearth.com) published on the brand''s own program page; application runs through Impact", "credibility": "Well-known plant-based pet-food pioneer, but program details on its own site are thin and partly dated", "niche_fit": "Plant-based dog food is a distinctive, debate-friendly pet-nutrition niche with a loyal niche audience", "opportunity_availability": "Standard Impact application, no follower minimum published", "ugc_evidence": "The brand runs a network affiliate program and a listed creator program, but its own program page is framed for veterinary partners rather than creators"}'::jsonb);
  insert into public.brands (name, website, description, country, status) values ('Neurable', 'https://www.neurable.com', 'US neurotechnology company selling the Neurable One: $499 premium noise-cancelling headphones with twelve EEG sensors in the ear pads that track focus, stress, load and sleepiness in its app. Its affiliate program pays partners a percentage of every referred sale, with a personal free-shipping code and a long cookie.', 'United States', 'published') returning id into bid;
