  insert into public.opportunities (brand_id, title, application_url, source_url, status, opportunity_type) values (bid, 'Neurable Affiliate Program — 10% on $499 EEG headphones, 120-day cookie, no minimum payout (affiliate@neurable.com)', 'https://www.neurable.com/affiliate-program', 'https://www.neurable.com/affiliate-program', 'unverified', 'ugc');
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://www.neurable.com/affiliate-program', 'official_site', 'affiliate', 'Official Neurable affiliate page fetched in full: ''It costs $499 and we ship in the US. You earn 10% of that on every referred sale'' — about $49.90 a unit, paid on the product price before tax and shipping; a 120-day cookie plus a personal code; ''No minimum payout'' (one sale a quarter gets paid; commission held 30 days for the return window, payouts monthly in USD). The page publishes the program email affiliate@neurable.com. It makes no statement about an earnings cap — ''no minimum payout'' is a payout-threshold statement, not an earnings statement — so the cap is unknown.', 'verified', now());
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://www.neurable.com/affiliate-program', 'official_site', 'creator_program', 'The same official page is creator-first: ''Promote it your way — Video, newsletter, blog, social, whatever you already do'', a partner portal with product shots, logos and a creator brief, and first looks at new products for approved partners. Applications are read by hand and approved on audience fit, size and quality; the audience must be in the US; coupon/cashback sites and brand-name paid search are not eligible; the brand reviews health claims (not creative) before publication.', 'verified', now());
  insert into public.brand_scores (brand_id, niche_fit, ugc_evidence, compensation, contact_access, opportunity_availability, credibility, explanation) values (bid, 26, 15, 13, 12, 6, 3, '{"compensation": "10% of a $499 product is about $49.90 per sale with an unusually long 120-day cookie and no minimum payout; no cap statement published", "contact_access": "Dedicated program email (affiliate@neurable.com) published on the brand''s own page, plus the application form", "credibility": "CES award and Forbes/Wired/CNN coverage cited on the page, but a young single-product company", "niche_fit": "EEG focus-tracking headphones are a highly demonstrable, novel tech product for review and productivity content", "opportunity_availability": "Applications are hand-reviewed on audience fit, size and quality, and the audience must be US-based", "ugc_evidence": "Creator-first program copy, a partner portal with a creator brief, and first-look access for approved partners"}'::jsonb);
