  insert into public.brand_scores (brand_id, niche_fit, ugc_evidence, compensation, contact_access, opportunity_availability, credibility, explanation) values (bid, 26, 12, 13, 11, 8, 5, '{"compensation": "A flat 10% on every confirmed purchase is a strong smart-home rate, with fast payment 20 days after approval; no cap statement published", "contact_access": "Program email (affiliates.shopus@tp-link.com) published on the brand''s own affiliate page, plus free account sign-up", "credibility": "TP-Link is a global networking and smart-home leader running the program from its official US storefront", "niche_fit": "Smart cameras, doorbells, plugs and lighting are among the most reviewed and demonstrated smart-home products in UGC", "opportunity_availability": "Free account creation on the brand''s own store; no follower minimum published", "ugc_evidence": "The store''s own program explicitly welcomes social media influencers and content creators alongside review sites"}'::jsonb);
