  insert into public.opportunities (brand_id, title, application_url, source_url, status, opportunity_type) values (bid, 'Withings Affiliate Program — smartwatches and smart scales via CJ Affiliate (published rates conflict at 4%-9%)', 'https://getlasso.co/affiliate/withings/', 'https://getlasso.co/affiliate/withings/', 'unverified', 'ugc');
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://www.whichprogram.com/en/p/withings-affiliate', 'listing', 'affiliate', 'WhichProgram''s Withings entry records the program on CJ Affiliate and states, as stated by the network, a ''5% standard commission per sale''; the same index also surfaces an Awin listing at up to 6.9% with a 3-day cookie. No earnings-cap statement is published, so the cap is unknown.', 'publicly_reported', now());
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://getlasso.co/affiliate/withings/', 'listing', 'affiliate', 'Lasso''s Withings listing reports a split rate of 5.6% per sale for new customers and 4% for existing customers with a 30-day cookie, while older roundups cite 7%-9% from the brand''s own page against 5%-7% on its CJ profile. Because the published figures conflict (4% / 5% / 5.6% / up to 6.9% / 7%-9% depending on source and network), commission_rate is null with the conflict recorded here; the CJ Affiliate route is the one consistently documented, including in Trainerize''s step-by-step Withings-via-CJ sign-up guide.', 'publicly_reported', now());
  insert into public.brand_scores (brand_id, niche_fit, ugc_evidence, compensation, contact_access, opportunity_availability, credibility, explanation) values (bid, 25, 11, 8, 8, 8, 5, '{"compensation": "Published rates conflict across sources and networks (4% to 9%), so no rate can be credited until verified in-network", "contact_access": "Application runs through CJ Affiliate; no public partnerships email found", "credibility": "Pioneer health-tech brand with a long-established device ecosystem and network program", "niche_fit": "Smart scales, hybrid smartwatches and blood-pressure monitors are staple health-tech review products with rich app data to show on camera", "opportunity_availability": "Standard CJ application, no follower minimum published", "ugc_evidence": "Long-running network publisher program aimed at tech and fitness reviewers; no dedicated creator tier published"}'::jsonb);
